import {artists,tracks,artistById,tracksFor,collaborationEdges,shortestPaths,dnaFor} from './data.js';
const $=(s,el=document)=>el.querySelector(s);
const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={
  network:'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="5" r="2"/><circle cx="20" cy="5" r="2"/><circle cx="4" cy="19" r="2"/><circle cx="20" cy="19" r="2"/><path d="m6 7 4 3m4 0 4-3M6 17l4-3m4 0 4 3"/>',
  sliders:'<path d="M5 3v6m0 5v7M12 3v12m0 5v1M19 3v2m0 5v11"/><circle cx="5" cy="11.5" r="2.5"/><circle cx="12" cy="17.5" r="2.5"/><circle cx="19" cy="7.5" r="2.5"/>',
  dna:'<path d="M6 3c0 8 12 10 12 18M18 3C18 11 6 13 6 21M6 4h12M7 8h10M7 16h10M6 20h12M10 12h4"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/>',
  search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  swap:'<path d="M3 8h17m-4-4 4 4-4 4M21 16H4m4-4-4 4 4 4"/>',
  expand:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',
  reset:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>',
  music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',
  plus:'<path d="M5 12h14M12 5v14"/>',minus:'<path d="M5 12h14"/>',
  share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v8h14v-8"/>',check:'<path d="m5 12 4 4L19 6"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'
};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.network}</svg>`;
function fillIcons(){ $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon)); }
const safeStore={get(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}};
const savedSelection=safeStore.get('rapdna-selected',[]);
const state={page:'explore',from:'masiwei',to:'aire',showProducers:true,paths:null,pathIndex:0,graphMode:'network',zoom:1,panX:0,panY:0,selected:new Set((Array.isArray(savedSelection)?savedSelection:[]).filter(id=>tracks.some(t=>t.id===id)).slice(0,10)),report:null};
const main=$('#main-content'),dialog=$('#detail-dialog');
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function openDialog(html){$('#dialog-content').innerHTML=html;fillIcons();if(!dialog.open)dialog.showModal();}
$('.dialog-close').onclick=()=>dialog.close();
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function about(){openDialog(`<div class="eyebrow">AN INDEPENDENT MUSIC EXPERIMENT</div><h2 class="dialog-title">声音背后，是相连的人。</h2><p class="dialog-subtitle">RAP DNA 希望把中文说唱的创作者关系，变成可以探索的音乐地图。</p><div class="evidence-note"><strong>当前为交互 Demo，所有关系均未完成核验</strong>人物名称用于说明产品场景。除构想中提到的两首作品外，其余曲目均为虚构演示内容；所有制作人署名均为模拟字段，不能作为音乐资料引用。</div><div class="dialog-section">这个 Demo 可以做什么？</div><p class="dialog-empty">① 选择两位 Rapper，计算演示曲库中的最短合作路径。<br>② 点击人物、连线或作品，查看角色和数据状态。<br>③ 选择喜欢的作品，按单曲署名统计幕后创作者。<br>④ 根据每日题目猜出中间人，查看作品路径并分享结果。</p><div class="dialog-section">数据边界</div><p class="dialog-empty">“最短”仅相对于当前收录数据。共同制作人与共同演唱分别呈现；专辑级署名不自动下放到单曲。当前没有播放授权、音乐平台登录或真实曲库 API，选择与挑战进度仅保存在本机浏览器。正式版需要独立核验署名，并为每条关系附上原始来源和核验日期。</p>`);}
$('#about').onclick=about;$('#help').onclick=about;
const pageNames={explore:'探索宇宙',producers:'制作人档案',dna:'我的音乐 DNA',challenge:'每日挑战'};
function navigate(page){if(!pageNames[page])page='explore';if(location.hash!==`#${page}`)history.pushState(null,'',`#${page}`);render(page);window.scrollTo({top:0,behavior:'instant'});}
function render(page){
  if(!pageNames[page])page='explore';
  state.page=page;
  $$('.nav-item').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  $('#breadcrumb').textContent=pageNames[page];
  if(page==='explore')renderExplore();else if(page==='producers')renderProducers();else if(page==='dna')renderDNA();else renderChallenge();
  fillIcons();
}
$$('.nav-item').forEach(el=>el.onclick=()=>navigate(el.dataset.page));
window.addEventListener('hashchange',()=>{render(location.hash.slice(1));window.scrollTo({top:0,behavior:'instant'});});
const performers=artists.filter(a=>!a.role);
const options=selected=>performers.map(a=>`<option value="${a.id}" ${selected===a.id?'selected':''}>${esc(a.name)}</option>`).join('');
const hero=(eyebrow,title,description,stats='')=>`<section class="hero"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${stats}</section>`;
function renderExplore(){
  const count=artists.filter(a=>!a.hidden).length;
  main.innerHTML=hero('EXPLORE THE CONNECTIONS','每一首歌，<em>都有迹可循。</em>','从你喜欢的声音出发，发现中文说唱里意想不到的连接。',`<div class="hero-stats"><div><b>${String(count).padStart(2,'0')}</b><span>演示音乐人</span></div><div><b>${tracks.length}</b><span>示例作品</span></div><div><b>${collaborationEdges().length}</b><span>合作连线</span></div></div>`)+`
    <form class="finder" id="finder"><div class="field"><label for="from-artist">START WITH / 从谁出发</label><div class="select-wrap">${icon('search')}<select id="from-artist" aria-label="起点 Rapper">${options(state.from)}</select></div></div><button type="button" class="swap-button" id="swap" aria-label="交换起点与终点">${icon('swap')}</button><div class="field"><label for="to-artist">FIND A WAY TO / 想连接谁</label><div class="select-wrap">${icon('search')}<select id="to-artist" aria-label="终点 Rapper">${options(state.to)}</select></div></div><button class="primary" type="submit">发现关联 ${icon('arrow')}</button></form>
    <div class="suggestions"><span>试试这组连接</span><button data-pair="masiwei,aire">马思唯 ↔ 艾热 AIR</button><button data-pair="knowknow,jonyj">KnowKnow ↔ Jony J</button><button data-pair="asen,gai">Asen ↔ GAI</button></div>
    <section class="graph-panel" aria-label="音乐人关系网络"><div class="panel-toolbar"><div class="graph-tabs" role="tablist" aria-label="关系展示方式"><button id="network-tab" role="tab" aria-selected="${state.graphMode==='network'}" class="${state.graphMode==='network'?'active':''}">合作网络</button><button id="works-tab" role="tab" aria-selected="${state.graphMode==='works'}" class="${state.graphMode==='works'?'active':''}">作品视角</button></div><div class="toolbar-right"><span class="toolbar-caption">每条连线，都由作品连接</span><button class="toggle" id="producer-toggle" aria-pressed="${state.showProducers}"><span class="toggle-mark"></span>显示制作人</button></div></div><div id="graph-content"></div><div id="path-content"></div><div class="graph-bottom"><span><span class="live-dot"></span>示例网络 · 点击节点探索，拖动或缩放地图</span><button class="text-link" id="reset-network">重置视图 ${icon('reset')}</button></div></section>
    <div class="section-heading"><h2>换个角度，继续发现 <span>KEEP DIGGING</span></h2><button class="text-link" id="random-explore">随便逛逛 ${icon('arrow')}</button></div>
    <section class="discovery-grid" aria-label="更多探索方式"><button class="discovery-card" data-go="producers"><div class="card-kicker">${icon('sliders')} BEHIND THE SOUND</div><h3>你喜欢的歌，<br>可能出自同一双手。</h3><p>走到聚光灯背后，认识连接不同声音的制作人。</p><div class="card-art"></div><div class="card-bottom"><span><span class="card-number">03</span> 位制作人，等待被发现</span>${icon('arrow')}</div></button><button class="discovery-card" data-go="dna"><div class="card-kicker">${icon('dna')} YOUR MUSICAL FINGERPRINT</div><h3>找到你的幕后音乐 DNA</h3><p>选几首喜欢的歌，看看谁反复出现在你的音乐世界。</p><div class="dna-art">${[25,45,65,35,55,75,43,61,30].map(h=>`<i style="--h:${h}px"></i>`).join('')}</div><div class="card-bottom"><span>生成我的 DNA 报告</span>${icon('arrow')}</div></button><button class="discovery-card" data-go="challenge"><div class="card-kicker orange">${icon('bolt')} THE DAILY CONNECTION</div><h3>两位 Rapper，一个中间人。</h3><p>你的说唱知识，够连接这两个人吗？来试试今日挑战。</p><div class="challenge-art">06°</div><div class="card-bottom"><span>今日挑战 · 等你接招</span>${icon('arrow')}</div></button></section>`;
  $('#finder').onsubmit=e=>{e.preventDefault();state.from=$('#from-artist').value;state.to=$('#to-artist').value;findPath();};
  $('#from-artist').onchange=e=>state.from=e.target.value;$('#to-artist').onchange=e=>state.to=e.target.value;
  $('#swap').onclick=()=>{[state.from,state.to]=[state.to,state.from];$('#from-artist').value=state.from;$('#to-artist').value=state.to;if(state.paths!==null)findPath();};
  $$('[data-pair]').forEach(btn=>btn.onclick=()=>{[state.from,state.to]=btn.dataset.pair.split(',');$('#from-artist').value=state.from;$('#to-artist').value=state.to;findPath();});
  $$('[data-go]').forEach(btn=>btn.onclick=()=>navigate(btn.dataset.go));
  $('#random-explore').onclick=()=>openArtist(artists.filter(a=>!a.hidden)[Math.floor(Math.random()*count)].id);
  $('#producer-toggle').onclick=e=>{state.showProducers=!state.showProducers;e.currentTarget.setAttribute('aria-pressed',state.showProducers);renderGraph();};
  $('#network-tab').onclick=()=>setGraphMode('network');$('#works-tab').onclick=()=>setGraphMode('works');
  $('#reset-network').onclick=()=>{state.paths=null;state.pathIndex=0;state.zoom=1;state.panX=state.panY=0;setGraphMode('network');renderPath();};
  renderGraph();renderPath();
}
function setGraphMode(mode){state.graphMode=mode;for(const [id,value] of [['network-tab','network'],['works-tab','works']]){$('#'+id).classList.toggle('active',value===mode);$('#'+id).setAttribute('aria-selected',value===mode);}renderGraph();}
function findPath(){state.paths=shortestPaths(state.from,state.to);state.pathIndex=0;state.zoom=1;state.panX=state.panY=0;setGraphMode('network');renderPath();if(!state.paths.length)toast('当前演示曲库尚未收录可连接这两人的合作。');else if(state.from===state.to)toast('起点与终点是同一位音乐人，无需经过合作连线。');else toast(`在演示曲库中找到 ${state.paths.length} 条最短路径`);}
function renderGraph(){
  const holder=$('#graph-content');if(!holder)return;
  if(state.graphMode==='works'){
    holder.innerHTML=`<div class="song-network"><div class="song-hint">共享署名，是发现下一首歌的线索。以下为示例作品，点击查看演唱与制作角色。</div>${tracks.map(t=>trackRow(t)).join('')}</div>`;bindTracks(holder);return;
  }
  const path=state.paths?.[state.pathIndex]||[], pathKeys=new Set(path.slice(1).map((id,i)=>[path[i],id].sort().join('|')));
  const edges=collaborationEdges(state.showProducers).filter(e=>!artistById(e.a).hidden&&!artistById(e.b).hidden);
  const nodes=artists.filter(a=>!a.hidden&&(state.showProducers||!a.role));
  holder.innerHTML=`<div class="graph-stage" id="graph-stage"><div class="graph-topnote">A LIVING MAP OF <b>CHINESE HIP-HOP</b></div><div class="graph-watermark">CONNECTED BY SOUND.</div><svg viewBox="0 0 1120 570" role="img" aria-labelledby="graph-title"><title id="graph-title">中文说唱演示合作网络。节点可点击查看档案，连线代表示例共同作品。</title><defs><radialGradient id="disc-shade"><stop offset="0" stop-color="#6c7554"/><stop offset=".4" stop-color="#38412d"/><stop offset="1" stop-color="#202a1c"/></radialGradient><radialGradient id="main-disc"><stop offset="0" stop-color="#c28b51"/><stop offset=".45" stop-color="#8c6840"/><stop offset="1" stop-color="#4d422d"/></radialGradient></defs><g id="graph-transform">${edges.map(e=>{const a=artistById(e.a),b=artistById(e.b),isProducer=a.role||b.role,key=[e.a,e.b].sort().join('|'),dy=(b.x-a.x)*.13;return `<path class="graph-edge ${isProducer?'producer-edge':''} ${pathKeys.has(key)?'highlight':''}" d="M ${a.x} ${a.y} Q ${(a.x+b.x)/2} ${(a.y+b.y)/2+dy} ${b.x} ${b.y}" data-edge="${e.tracks[0]}" style="cursor:pointer" pointer-events="stroke"><title>${esc(a.name)} × ${esc(b.name)} · ${e.tracks.length} 首示例作品</title></path>`;}).join('')}${nodes.map(a=>{const r=a.size,isMain=a.id==='masiwei';return `<g class="graph-node ${path.includes(a.id)?'highlight':''} ${path.length&&!path.includes(a.id)?'dim':''}" transform="translate(${a.x} ${a.y})" role="button" tabindex="0" aria-label="查看 ${esc(a.name)} 的档案" data-artist="${a.id}"><circle class="node-ring" r="${r+9}"/><circle class="node-disc" r="${r}" fill="url(#${isMain?'main-disc':'disc-shade'})"/>${[.88,.77,.65].map(n=>`<circle r="${r*n}" fill="none" stroke="${a.color}" stroke-opacity=".13" stroke-width=".6"/>`).join('')}<circle r="${r*.44}" fill="${a.color}" fill-opacity="${isMain?'.45':'.16'}"/><text class="node-initial" text-anchor="middle" dominant-baseline="central" font-size="${a.short.length>2?r*.46:r*.76}">${esc(a.short)}</text><text class="node-name" y="${r+27}" text-anchor="middle">${esc(a.name)}</text><text class="node-type" y="${r+42}" text-anchor="middle">${a.role?'PRODUCER':a.en}</text></g>`;}).join('')}</g></svg><div class="graph-legend"><span><i class="legend-dot"></i>Rapper</span><span><i class="legend-dot producer"></i>制作人</span><span><i class="legend-line"></i>示例共同作品</span></div><div class="graph-controls"><button id="zoom-in" aria-label="放大">${icon('plus')}</button><button id="zoom-out" aria-label="缩小">${icon('minus')}</button><button id="zoom-reset" aria-label="恢复地图缩放">${icon('expand')}</button></div></div>`;
  $$('[data-artist]',holder).forEach(el=>{el.onclick=()=>{if(!dragMoved)openArtist(el.dataset.artist);};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openArtist(el.dataset.artist);}};});
  $$('[data-edge]',holder).forEach(el=>el.onclick=()=>{if(!dragMoved)openTrack(el.dataset.edge);});
  $('#zoom-in').onclick=()=>zoom(.2);$('#zoom-out').onclick=()=>zoom(-.2);$('#zoom-reset').onclick=()=>{state.zoom=1;state.panX=state.panY=0;applyTransform();};
  const stage=$('#graph-stage');let drag=null,dragMoved=false;
  stage.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;drag={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY};dragMoved=false;});
  stage.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>6){dragMoved=true;stage.classList.add('dragging');stage.setPointerCapture(e.pointerId);}if(dragMoved){const scale=1120/$('svg',stage).getBoundingClientRect().width;state.panX=drag.px+dx*scale;state.panY=drag.py+dy*scale;applyTransform();}});
  const end=()=>{drag=null;stage.classList.remove('dragging');};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);stage.addEventListener('pointerleave',e=>{if(!stage.hasPointerCapture(e.pointerId))end();});
  stage.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();zoom(e.deltaY>0?-.1:.1);}},{passive:false});
  applyTransform();
}
function zoom(amount){state.zoom=Math.max(.55,Math.min(2.2,state.zoom+amount));applyTransform();}
function applyTransform(){const el=$('#graph-transform');if(el)el.setAttribute('transform',`translate(${560+state.panX} ${285+state.panY}) scale(${state.zoom}) translate(-560 -285)`);}
function renderPath(){
  const holder=$('#path-content');if(!holder)return;if(state.paths===null){holder.innerHTML='';return;}
  if(!state.paths.length){holder.innerHTML='<div class="empty-state"><b>这段连接，还等你一起发现。</b>当前演示曲库没有可用路径，试试其他音乐人。<br>未收录不代表他们从未合作。</div>';return;}
  const path=state.paths[state.pathIndex];
  holder.innerHTML=`<div class="path-result"><div class="path-result-header"><span>${path.length===1?'你已在终点':`经过 <b>${Math.max(0,path.length-2)} 位中间人</b>，连接了两种声音。`}</span>${state.paths.length>1?`<div class="path-switcher"><button id="path-prev" aria-label="上一条路径">‹</button><span>${state.pathIndex+1} / ${state.paths.length} 条最短路径</span><button id="path-next" aria-label="下一条路径">›</button></div>`:'<span class="demo-badge">DEMO CONNECTION</span>'}</div><div class="path-chain">${path.map((id,i)=>{const a=artistById(id),t=i?tracks.find(t=>t.artists.includes(path[i-1])&&t.artists.includes(id)):null;return `${t?`<button class="path-track" data-track="${t.id}">${esc(t.title)}<br><small>查看作品与数据状态 ↗</small></button>`:''}<button class="path-person" data-person="${id}"><span>${esc(a.short)}</span>${esc(a.name)}</button>`;}).join('')}</div><div class="scope-note">${path.length===1?'起点与终点为同一位音乐人，距离为 0。':'最短路径仅基于当前演示曲库的共同演唱记录；不含通过共同制作人建立的间接关系。'}所有演示关系均未完成独立核验。</div></div>`;
  bindTracks(holder);$$('[data-person]',holder).forEach(b=>b.onclick=()=>openArtist(b.dataset.person));
  if($('#path-prev')){const cycle=step=>{state.pathIndex=(state.pathIndex+step+state.paths.length)%state.paths.length;renderGraph();renderPath();};$('#path-prev').onclick=()=>cycle(-1);$('#path-next').onclick=()=>cycle(1);}
}
function trackRow(t,role=''){return `<button class="track-row" data-track="${t.id}"><span class="cover ${t.cover}">${t.title.slice(0,1)}</span><span class="track-info"><b>${esc(t.title)}</b><small>${t.artists.map(id=>esc(artistById(id).name)).join(' / ')}</small></span><span class="track-role">${esc(role||'示例作品')}<small>${t.year}</small></span></button>`;}
function bindTracks(root=document){$$('[data-track]',root).forEach(b=>b.onclick=()=>openTrack(b.dataset.track));}
function openTrack(id){
  const t=tracks.find(t=>t.id===id);if(!t)return;
  openDialog(`<div class="eyebrow">THE STORY BEHIND THE TRACK</div><h2 class="dialog-title">${esc(t.title)}</h2><div class="dialog-subtitle">${t.artists.map(id=>esc(artistById(id).name)).join(' / ')} · ${t.year}（演示年份）</div><div class="dialog-section">单曲级署名 / DEMO CREDITS</div>${t.artists.map(id=>`<button class="credit-row" style="width:100%" data-credit="${id}">${esc(artistById(id).name)}<span>演唱 ↗</span></button>`).join('')}${t.credits.map(([id,role])=>`<button class="credit-row" style="width:100%" data-credit="${id}">${esc(artistById(id).name)}<span>${role} ↗</span></button>`).join('')}<div class="evidence-note"><strong>数据状态：未核验 · ${t.id.startsWith('demo')?'虚构作品':'构想案例'}</strong>${esc(t.origin)}<br>本页不提供已核实的原始署名来源，不能作为合作关系证据引用。</div><div class="dialog-actions"><button class="text-link" id="add-to-dna">${state.selected.has(id)?'已在 DNA 选择中 ✓':'加入我的 DNA 选择 +'} </button><button class="text-link" id="go-to-dna">前往 DNA 报告 ${icon('arrow')}</button></div>`);
  $$('[data-credit]').forEach(b=>b.onclick=()=>openArtist(b.dataset.credit));
  $('#add-to-dna').onclick=()=>{state.selected.add(id);safeStore.set('rapdna-selected',[...state.selected]);$('#add-to-dna').textContent='已在 DNA 选择中 ✓';toast('已加入 DNA 选择');};
  $('#go-to-dna').onclick=()=>{dialog.close();navigate('dna');};
}
function openArtist(id){
  const a=artistById(id);if(!a)return;const list=tracksFor(id);const collaborators=new Set(list.flatMap(t=>t.artists).filter(i=>i!==id));
  openDialog(`<div class="eyebrow">${a.role?'BEHIND THE SOUND':'ARTIST CONNECTIONS'}</div><h2 class="dialog-title">${esc(a.name)}</h2><p class="dialog-subtitle">${esc(a.en)} · ${a.role?'幕后音乐人':'Rapper'}<br>收录 ${list.length} 首演示作品 · 关联 ${collaborators.size} 位演唱者</p><div class="info-strip">以下为模拟档案，用来体验人物 → 作品 → 合作人的探索流程。</div><div class="dialog-section">参与作品 / 按演示年份排列</div><div class="track-list">${list.sort((x,y)=>y.year-x.year).map(t=>trackRow(t,a.role?t.credits.filter(([p])=>p===id).map(([,r])=>r).join(' / '):'演唱')).join('')||'<p class="dialog-empty">还没有收录此音乐人的合作资料。</p>'}</div>${!a.role&&!a.hidden?`<div class="dialog-actions"><button class="primary" id="start-here">从 TA 出发 ${icon('arrow')}</button></div>`:''}`);
  bindTracks(dialog);if($('#start-here'))$('#start-here').onclick=()=>{state.from=id;state.paths=null;dialog.close();if(state.to===id)state.to=performers.find(p=>p.id!==id&&!p.hidden).id;navigate('explore');};
}
function renderProducers(){
  main.innerHTML=hero('BEHIND THE SOUND','认识那些，<em>塑造声音的人。</em>','制作、编曲、混音，每一个角色，都值得被听见。')+`<div class="info-strip">演示档案：以下作品与制作署名用于展示功能，均未经独立核验。各角色按单曲分别记录，不从专辑署名推定。</div><section class="content-grid">${artists.filter(a=>a.role).map(a=>{const list=tracksFor(a.id),people=new Set(list.flatMap(t=>t.artists)),roles=[...new Set(list.flatMap(t=>t.credits.filter(([id])=>id===a.id).map(([,role])=>role)))];return `<article class="producer-card"><div class="producer-avatar"><span>${a.short}</span></div><h2>${esc(a.name)}</h2><p>${roles.join(' / ')}<br>从熟悉的声音，听见新的连接。</p><div class="producer-stats"><div><b>${list.length.toString().padStart(2,'0')}</b><span>示例单曲署名</span></div><div><b>${people.size.toString().padStart(2,'0')}</b><span>关联演唱者</span></div></div><button class="text-link" data-producer="${a.id}">探索制作档案 ${icon('arrow')}</button></article>`;}).join('')}</section><div class="section-heading"><h2>从一首作品听起 <span>FOLLOW THE CREDITS</span></h2></div><div class="content-grid">${tracks.slice(0,6).map(t=>trackRow(t,t.credits.map(([id])=>artistById(id).name).join(' / '))).join('')}</div>`;
  $$('[data-producer]').forEach(b=>b.onclick=()=>openArtist(b.dataset.producer));bindTracks(main);
}
function renderDNA(){
  main.innerHTML=hero('YOUR MUSICAL FINGERPRINT','你的偏爱，<em>有它的幕后线索。</em>','选出你喜欢的作品，看看哪些创作者反复出现在你的音乐里。')+`<div class="split-layout"><section class="surface"><h2>把喜欢的声音放在一起</h2><p>选择 3–10 首示例作品，发现共享制作署名。这里不会分析你的音频或收听记录。</p><div class="track-picker">${tracks.map(t=>`<label class="track-choice"><span class="cover ${t.cover}">${t.title.slice(0,1)}</span><span class="track-info"><b>${esc(t.title)}</b><small>${esc(artistById(t.artists[0]).name)}</small></span><input type="checkbox" value="${t.id}" aria-label="选择 ${esc(t.title)}" ${state.selected.has(t.id)?'checked':''}></label>`).join('')}</div><div class="picker-actions"><span id="selected-count">已选 ${state.selected.size} / 10 首</span><button class="primary" id="generate-dna" ${state.selected.size<3?'disabled':''}>发现我的 DNA ${icon('arrow')}</button></div></section><section class="surface dna-report" id="dna-report" aria-live="polite"></section></div>`;
  $$('.track-choice input').forEach(input=>input.onchange=()=>{
    if(input.checked&&state.selected.size>=10){input.checked=false;toast('最多选择 10 首作品');return;}
    input.checked?state.selected.add(input.value):state.selected.delete(input.value);state.report=null;safeStore.set('rapdna-selected',[...state.selected]);$('#selected-count').textContent=`已选 ${state.selected.size} / 10 首`;$('#generate-dna').disabled=state.selected.size<3;renderReport();
  });
  $('#generate-dna').onclick=()=>{state.report=dnaFor([...state.selected]);renderReport();if(matchMedia('(max-width:640px)').matches)$('#dna-report').scrollIntoView({behavior:'smooth',block:'start'});};renderReport();
}
function renderReport(){
  const holder=$('#dna-report');if(!holder)return;
  if(!state.report){holder.innerHTML=`<div class="dna-placeholder"><span>✳</span><div class="eyebrow" style="justify-content:center">YOUR TASTE HAS A PATTERN</div><h2 style="margin-top:20px">喜欢的歌背后，藏着谁？</h2><p>选好作品，生成属于你的幕后音乐人报告。<br>也许下次，你会先记住制作人的名字。</p><button class="text-link" id="try-dna">试试一组示例选择 ${icon('arrow')}</button></div>`;$('#try-dna').onclick=()=>{state.selected=new Set(['do-it','wuyan','demo-01','demo-03','demo-08']);state.report=dnaFor([...state.selected]);safeStore.set('rapdna-selected',[...state.selected]);renderDNA();};return;}
  const top=state.report[0],n=state.selected.size;
  holder.innerHTML=`<div class="eyebrow">RAP DNA / PERSONAL REPORT</div><div class="report-title">CONNECTED BY TASTE.</div><p>在你选中的 ${n} 首示例作品里，出现最多的幕后创作者是</p><div class="report-top-person">${esc(artistById(top.id).name)}</div><div class="report-meta">${top.count} / ${n} 首共同署名 · 占比 ${Math.round(top.count/n*100)}%</div>${state.report.map(row=>`<div class="report-row"><button class="report-row-head" style="width:100%;padding:0" data-dna-person="${row.id}">${esc(artistById(row.id).name)}<span>${row.count} 首 / ${Math.round(row.count/n*100)}%</span></button><div class="report-bar"><i style="width:${row.count/n*100}%"></i></div><div class="report-role">${[...row.roles].join(' · ')} · 同一首作品参与多个角色只计 1 首</div></div>`).join('')}<div class="evidence-note"><strong>演示报告 · 依据模拟单曲署名</strong>共享创作者是发现音乐的线索，不代表作品风格相似。统计不包含专辑级推定署名。</div><div class="report-actions"><button class="text-link" id="download-dna">${icon('download')} 保存报告卡片</button><button class="text-link" id="share-dna">${icon('share')} 分享文字</button></div>`;
  $$('[data-dna-person]').forEach(b=>b.onclick=()=>openArtist(b.dataset.dnaPerson));$('#download-dna').onclick=downloadReport;$('#share-dna').onclick=()=>shareText(`我的 RAP DNA（演示）\n选中 ${n} 首作品，${top.count} 首共同署名指向 ${artistById(top.id).name}。\n发现声音背后的人。\n${location.href}`);
}
function downloadReport(){
  const n=state.selected.size,top=state.report[0];
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="1000" viewBox="0 0 800 1000"><rect width="800" height="1000" fill="#171d15"/><g fill="none" stroke="#708056" opacity=".15"><circle cx="700" cy="160" r="240"/><circle cx="700" cy="160" r="220"/><circle cx="700" cy="160" r="200"/><circle cx="700" cy="160" r="180"/></g><text x="65" y="100" fill="#e9a65e" font-family="Arial,sans-serif" font-weight="bold" font-size="35">RAP DNA</text><text x="65" y="145" fill="#a2ae91" font-family="sans-serif" font-size="17">YOUR MUSICAL FINGERPRINT / 演示报告</text><text x="65" y="242" fill="#eeeee4" font-family="sans-serif" font-size="30">我的偏爱，有它的幕后线索。</text><text x="65" y="305" fill="#a2ae91" font-family="sans-serif" font-size="19">${n} 首示例作品中，反复出现的名字</text><text x="65" y="415" fill="#e9a65e" font-family="sans-serif" font-size="64" font-weight="bold">${esc(artistById(top.id).name)}</text><text x="65" y="465" fill="#a2ae91" font-family="sans-serif" font-size="20">${top.count} / ${n} 首作品 · 共同署名占比 ${Math.round(top.count/n*100)}%</text>${state.report.map((r,i)=>`<text x="65" y="${560+i*86}" fill="#eeeee4" font-family="sans-serif" font-size="21">${esc(artistById(r.id).name)}</text><text x="735" y="${560+i*86}" fill="#a2ae91" font-family="sans-serif" font-size="18" text-anchor="end">${r.count} 首</text><rect x="65" y="${577+i*86}" width="670" height="7" rx="3" fill="#343e2a"/><rect x="65" y="${577+i*86}" width="${670*r.count/n}" height="7" rx="3" fill="#e9a65e"/>`).join('')}<path d="M65 870H735" stroke="#414c34"/><text x="65" y="912" fill="#a2ae91" font-family="sans-serif" font-size="15">DEMO · 基于模拟单曲署名，不代表真实作品资料</text><text x="65" y="950" fill="#e9a65e" font-family="sans-serif" font-size="16">MADE FOR THE CULTURE.</text></svg>`;
  const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='RAP-DNA-demo-report.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报告卡片已保存为 SVG，可直接打开或分享');
}
async function shareText(text){try{await navigator.clipboard.writeText(text);toast('分享文字已复制');}catch{openDialog(`<div class="eyebrow">SHARE YOUR CONNECTION</div><h2 class="dialog-title">分享这次发现</h2><p class="dialog-subtitle">浏览器未开放剪贴板，请复制下方文字。</p><textarea readonly style="width:100%;height:180px;background:#131911;color:#eeeee4;border:1px solid #4b563b;padding:15px;line-height:2">${esc(text)}</textarea>`);$('textarea',dialog).select();}}
function dailyChallenge(){
  const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const pairs=[];for(let i=0;i<performers.length;i++)for(let j=i+1;j<performers.length;j++){const paths=shortestPaths(performers[i].id,performers[j].id);if(paths[0]?.length===3)pairs.push({from:performers[i].id,to:performers[j].id,paths});}
  const hash=[...date].reduce((n,c)=>n*31+c.charCodeAt(0),0)>>>0;
  return {date,...pairs[hash%pairs.length]};
}
function renderChallenge(){
  const q=dailyChallenge(),key='rapdna-challenge-'+q.date;
  let progress=safeStore.get(key,{attempts:0,solved:false,started:Date.now(),hint:false});
  const left=artistById(q.from),right=artistById(q.to);
  main.innerHTML=hero('THE DAILY CONNECTION','你的说唱知识，<em>能连接他们吗？</em>','每天一条合作路径，用作品找到两位 Rapper 之间的中间人。')+`<div class="challenge-layout"><section class="surface challenge-board"><div class="challenge-date">DAILY / ${esc(q.date)} · 北京时间</div><h2>少一个名字，多一点好奇。</h2><p class="challenge-instruction">在当前示例曲库里，谁与两位音乐人都共同演唱过作品？<br>可能存在多个正确答案，找到其中一位就算成功。</p><div class="challenge-nodes"><div class="challenge-person"><div class="challenge-disc">${left.short}</div>${left.name}</div><div class="challenge-line"></div><div class="challenge-person unknown"><div class="challenge-disc">?</div>中间人</div><div class="challenge-line"></div><div class="challenge-person"><div class="challenge-disc">${right.short}</div>${right.name}</div></div><form class="challenge-answer" id="challenge-form"><select id="challenge-choice" aria-label="选择中间音乐人"><option value="">选择你猜的音乐人</option>${performers.filter(a=>!a.hidden&&a.id!==q.from&&a.id!==q.to).map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select><button class="primary" type="submit">提交答案 ${icon('arrow')}</button></form><div class="challenge-feedback" id="challenge-feedback" role="status"></div><div class="dialog-actions"><button class="text-link" id="challenge-hint">需要一点提示？</button><span class="demo-badge" id="challenge-attempts"></span></div></section><section class="surface"><div class="eyebrow">HOW TO PLAY</div><h2 style="margin-top:20px">用合作作品，把他们连起来。</h2><ol class="rules-list"><li>只计算同一首作品中的共同演唱，不包含共同制作人。</li><li>选择一位与两端都有直接合作的音乐人。</li><li>答对后，展开完整作品链，分享你的发现。</li></ol><div class="evidence-note"><strong>每日演示挑战</strong>题目由模拟曲库按北京时间日期确定，同一天所有访客看到相同题目。挑战关系不代表真实音乐资料。</div><button class="text-link" id="challenge-explore" style="margin-top:25px">去关系图找找线索 ${icon('arrow')}</button></section></div>`;
  function showProgress(){
    $('#challenge-attempts').textContent=`已尝试 ${progress.attempts} 次${progress.hint?' · 已用提示':''}`;
    if(progress.solved){$('#challenge-feedback').innerHTML=`${icon('check')} 接上了！${esc(artistById(progress.answer).name)} 就是其中一位。<br>用时 ${progress.seconds} 秒 · ${progress.attempts} 次尝试 <div class="dialog-actions"><button class="text-link" id="reveal-path">查看完整作品链 ${icon('arrow')}</button><button class="text-link" id="share-challenge">分享成绩 ${icon('share')}</button></div>`;$('#challenge-choice').value=progress.answer;$('#challenge-choice').disabled=true;$('#challenge-form button').disabled=true;$('#challenge-hint').disabled=true;$('#reveal-path').onclick=()=>revealPath(progress.answer);$('#share-challenge').onclick=()=>shareText(`RAP DNA 每日挑战 · ${q.date}\n${left.name} ↔ ? ↔ ${right.name}\n${progress.attempts} 次猜出，${progress.seconds} 秒完成${progress.hint?'（使用提示）':''}。\n你能找到中间人吗？（示例曲库）\n${location.href}`);}
    else if(progress.hint){const mid=artistById(q.paths[0][1]);$('#challenge-feedback').textContent=`提示：其中一位正确音乐人的英文名以「${mid.en[0]}」开头。`;} 
  }
  function revealPath(answer){const chain=[q.from,answer,q.to];openDialog(`<div class="eyebrow">CONNECTION COMPLETE</div><h2 class="dialog-title">每一步，都有作品相连。</h2><p class="dialog-subtitle">${chain.map(id=>esc(artistById(id).name)).join(' → ')}</p><div class="track-list">${chain.slice(1).map((id,i)=>trackRow(tracks.find(t=>t.artists.includes(chain[i])&&t.artists.includes(id)))).join('')}</div><div class="evidence-note"><strong>演示关系 · 未核验</strong>作品与署名用于展示挑战玩法，点击作品可查看数据状态。</div>`);bindTracks(dialog);}
  $('#challenge-form').onsubmit=e=>{e.preventDefault();if(progress.solved)return;const answer=$('#challenge-choice').value;if(!answer){toast('先选择一位音乐人');return;}progress.attempts++;if(q.paths.some(p=>p[1]===answer)){progress.solved=true;progress.answer=answer;progress.seconds=Math.max(1,Math.round((Date.now()-progress.started)/1000));}safeStore.set(key,progress);showProgress();if(!progress.solved)$('#challenge-feedback').textContent='还差一点。演示曲库中，这位音乐人未与两端都形成直接合作，再试一次。';};
  $('#challenge-hint').onclick=()=>{progress.hint=true;safeStore.set(key,progress);showProgress();};$('#challenge-explore').onclick=()=>{state.from=q.from;state.to=q.to;state.paths=null;navigate('explore');};showProgress();
}
fillIcons();const initial=location.hash.slice(1);if(!pageNames[initial])history.replaceState(null,'','#explore');render(pageNames[initial]?initial:'explore');
